CREATE OR REPLACE FUNCTION public.data_use_consent_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.revoked_at IS NULL OR OLD.revoked_at>clock_timestamp()-interval '1 year' THEN
